{
  "lecture": [
    {
      "etiquette": "F21",
      "R1": {
        "valeur": 1,
        "passage": "à dépense égale, au moins deux composantes de plus en moyenne par monde à la fin de la course, contre le témoin à coût égal"
      },
      "R2": {
        "valeur": 1,
        "passage": "oracle après la course : composantes plantées couvertes, lois fausses promues, copies promues ; relais : coût en dollars de chaque rôle, génération après génération"
      },
      "R3": {
        "valeur": 1,
        "passage": "Rien n'est servi de plus aux proposeurs."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "Remplacer, dans le texte servi à chaque proposeur, la constante qui fixe le nombre de cartes demandées à chaque proposeur par le réglage de départ diminué d'un tiers, par excès."
      },
      "R6": {
        "valeur": 1,
        "passage": "environ 16 heures de processeur pour 24 graines, sans appel de proposeur ni de juge à modèle, le relevé des relais faisant foi, à peu près la moitié pour chacun des deux bras"
      },
      "R7": {
        "valeur": 0,
        "motif": "La chaîne causale affirme sans justification que réduire les reprises de l'archive réduit les candidates hors du nul et que cette réduction augmente la couverture, alors que les faits ne donnent pas ces relations."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F22",
      "R1": {
        "valeur": 1,
        "passage": "à calcul égal, au moins 20 % de composantes plantées couvertes en plus après six générations qu'une trajectoire unique à carnet continu"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes, lois fausses et copies promues, lues par l'oracle après la course ; dollars relevés par branche et par génération"
      },
      "R3": {
        "valeur": 0,
        "motif": "La branche poursuivie est choisie selon le nombre de lois retenues, ce qui fait dépendre la composition du verdict du juge sans rouvrir explicitement cette objection."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "garder la branche qui a retenu le plus de lois (égalité : la plus petite graine) et jeter les deux autres, journaux conservés."
      },
      "R6": {
        "valeur": 1,
        "passage": "environ 1,5 fois le coût d'une course témoin sur les horizons de branche, soit de l'ordre de 300 USD pour trente mondes et six générations, témoins compris"
      },
      "R7": {
        "valeur": 1,
        "passage": "Le carnet qui repart vide casse l'ancrage sur les premières idées, sans perdre ce que l'archive a acquis"
      },
      "N": {
        "valeur": "C5",
        "passage_fiche": "Après un horizon fixe de deux générations, la course continue depuis la branche qui a retenu le plus de lois ; les autres sont abandonnées.",
        "passage_catalogue": "après un horizon fixe, on **continue depuis la trajectoire au meilleur score**"
      }
    },
    {
      "etiquette": "F23",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle dans les retenues augmente d'au moins 30 % par rapport à la composition monolithique à une passe"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes, les représentants et les retenues, et nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 0,
        "motif": "La maximisation numérique de la distance de Jaccard impose une sélection par nouveauté des tuples sans nommer ni traiter l'objection à une prime numérique de nouveauté."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 0,
        "motif": "La procédure exige six tuples après filtrage sans préciser quoi faire lorsque moins de six tuples distincts restent disponibles."
      },
      "R6": {
        "valeur": 0,
        "motif": "Le prétendu contrôle négatif décrit un risque plutôt qu'un bras de contrôle, et l'expérience chiffrée utilise un témoin à coût supérieur ou égal sans fixer une comparaison à coût égal."
      },
      "R7": {
        "valeur": 0,
        "motif": "La diversité syntaxique des tuples ne justifie pas une hausse de couverture vraie, puisque le filtrage peut aussi imposer des traits de bruit ou exclure des traits utiles."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F24",
      "R1": {
        "valeur": 1,
        "passage": "à budget égal en dollars (arrêt de chaque bras au même montant relevé), le bras à deux demi-générations couvre au total au moins 10 % de composantes plantées de plus que le témoin"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes, comptées à part pour les conditionnelles et les autres, lois fausses et copies promues : lues par l'oracle une fois après chaque course"
      },
      "R3": {
        "valeur": 1,
        "passage": "une carte de B qui recopie une loi retenue en A est refusée comme copie par le nul mis à jour."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 1,
        "passage": "Dans la boucle de génération de l'orchestrateur, remplacer l'appel unique par proposeur (six cartes) par deux passes de trois cartes, A puis B, chacune en session neuve."
      },
      "R6": {
        "valeur": 1,
        "passage": "vingt mondes, deux bras, budget de quatre générations du témoin : environ 1,4 USD par génération, soit près de 225 USD en tout"
      },
      "R7": {
        "valeur": 1,
        "passage": "Avec deux passes de trois cartes par proposeur et l'archive mise à jour entre elles, la composante qui en dépend peut être proposée dans la même génération."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F25",
      "R1": {
        "valeur": 1,
        "passage": "À nombre de tirages frais égal et cartes identiques : le bras stratifié couvre, à l'étage des retenues, au moins 1,5 fois plus de composantes rares que le bras uniforme"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes par strate de masse (rare / globale), aux étages des représentants et des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "Rien de la stratification n'est servi aux proposeurs."
      },
      "R4": {
        "valeur": 1,
        "passage": "sa validité (espérance au plus 1 sous le nul) se tient conditionnellement à chaque jeu de traits et ne dépend donc pas de la loi selon laquelle les traits sont tirés"
      },
      "R5": {
        "valeur": 1,
        "passage": "(2) fixer d'avance, dans l'engagement scellé, l'effectif par strate : n/S épisodes frais par strate, où n est le nombre total actuel de tirages frais"
      },
      "R6": {
        "valeur": 1,
        "passage": "Rejeu des cartes déjà rendues sur mondes engendrés par programme ; quelques heures de calcul local, zéro appel de modèle, zéro dollar."
      },
      "R7": {
        "valeur": 1,
        "passage": "La stratification lève la borne de dilution (d ≤ r(A)·ln 2) sans un tirage de plus."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
